      SUBROUTINE SURVEYCC     PRINTING OF FLOOR COORDINATESCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'YAW.CIN'C ----------------------------------------------------------------------      INTEGER         J      REAL            ALONG, CSY, SHIFT, SNY      REAL            POS(3)C      ALONG = LC/UFLOOR(1)      DO 10 J = 1, 3      POS(J) = X0(4,J)/UFLOOR(1)   10 CONTINUEC      CSY = O(4,3,3)      SNY = O(4,3,1)      IF (CSY .EQ. 0.0) THEN        IF (SNY .GT. 0.0) YAW = 0.5*PI        IF (SNY .LT. 0.0) YAW = - 0.5*PI      ELSE        YAW = ATAN(SNY/CSY)        IF (CSY .LT. 0.0) THEN          SHIFT = SIGN(PI,SNY)          YAW = YAW + SHIFT        ENDIF        YAW = YAW/UFLOOR(2)      ENDIFC      PITCH = ASIN(O(4,3,2))/UFLOOR(2)C      IF (O(4,2,2) .NE. 0.0) ROLL = ATAN(O(4,1,2)/O(4,2,2))      IF (O(4,2,2) .EQ. 0.0 .AND. O(4,1,2) .GT. 0.0) ROLL = 0.5*PI      IF (O(4,2,2) .EQ. 0.0 .AND. O(4,1,2) .LT. 0.0) ROLL = - 0.5*PI      IF (O(4,2,2) .LT. 0.0) THEN        SHIFT = SIGN(PI,O(4,1,2))        ROLL = ROLL + SHIFT      ENDIF      ROLL = ROLL/UFLOOR(2)C      IF (UFLOOR(2) .LE. 0.1) THEN        WRITE (NOUT,1000) ALONG, XFLOOR(1), POS, XFLOOR(1), YAW, PITCH,     1                    ROLL, XFLOOR(2)      ELSE        WRITE (NOUT,1001) ALONG, XFLOOR(1), POS, XFLOOR(1), YAW, PITCH,     1                    ROLL, XFLOOR(2)      ENDIFC      IF (LAY191)     1    WRITE (NOUT,1002) LABEL(NUM), ALONG, POS, YAW, PITCH, ROLLC 1000 FORMAT (1H ,8X,F10.3,1X,A4,9X,3F11.4,1X,A4,1X,3F10.3,1X,A4) 1001 FORMAT (1H ,5X,F15.6,1X,A4,8X,3F13.5,1X,A4,1X,3F12.6,1X,A4) 1002 FORMAT (2H %,A4,F12.5,6E18.10)      LCPR = .TRUE.      RETURN      END